+const toolProducerSlug = "tool-builder"   // lockstep-tested against builderForPageType("tool")
+const toolPageRole = "tool"
+
+type ToolSourceResolution struct { ToolFamily, Producible bool; ProducerNeeded, Evidence string }
+
+// Role only — NOT a section-name heuristic: hero-tool/tool-guide-intro/tool-cta are ordinary
+// section components sharing the `tool-` prefix with tool FUNCTIONS, so a prefix test cannot
+// discriminate, and a non-tool page embedding a tool section is not this bug's class.
+func isToolRole(role string) bool { return role == toolPageRole }
+
+// ONE read per gate run.
+func siteToolFunctions(ctx, db, siteID) (map[string]bool, error) {
+	`SELECT DISTINCT cc.function FROM content_components cc
+	   JOIN page_components pc ON pc.component_id = cc.id
+	   JOIN pages p ON pc.page_id = p.id
+	  WHERE p.site_id = $1 AND cc.component_level='tool' AND cc.is_active = true
+	    AND cc.function IS NOT NULL AND cc.function <> ''`
+}
+
+// Mirrors the tool pipeline's naming contract: sanitiseFunction guarantees the `tool-`
+// prefix and the page is created with pages.name == cc.function, while
+// resolveToolPageIdentity still accepts a legacy bare-slug page.
+func toolFunctionCandidates(page planPageView) []string   // sections ∪ {Name, "tool-"+Name}
+
+func ResolveToolItemSource(page planPageView, siteTools map[string]bool) ToolSourceResolution {
+	if !isToolRole(page.Role) { return ToolSourceResolution{} }        // out of family
+	for _, c := range toolFunctionCandidates(page) {
+		if siteTools[c] { return ToolSourceResolution{ToolFamily:true, Producible:true, ...} }
+	}
+	return ToolSourceResolution{ToolFamily:true, Producible:false, ProducerNeeded: toolProducerSlug, ...}
+}
+
+func enforceToolItemSources(ctx, params, pages, existingPages []interface{}) []interface{} {
+	if params.DB == nil { warn; return pages }                          // fail open
+	siteID, err := uuid.Parse(...); if err != nil { warn; return pages } // fail open
+	// the common plan has no tool page at all — do not spend the census on it
+	if !anyToolPage { return pages }
+	siteTools, err := siteToolFunctions(...)
+	if err != nil { warn; return pages }   // INFRASTRUCTURE failure -> stand down entirely.
+	                                       // Holding every tool page on a transient DB error
+	                                       // would be the starvation failure §7 rules out,
+	                                       // arriving by accident.
+	for each plan page {
+		res := ResolveToolItemSource(view, siteTools)
+		if !res.ToolFamily || res.Producible { keep; continue }
+		if realisedKeys[view.Name] || realisedKeys[view.URL] {   // bugs_open/001 preserve guard
+			fileToolCapabilityGap(...); keep; continue            // receipt still filed
+		}
+		fileToolCapabilityGap(...); drops = append(drops, ...)
+	}
+	if len(drops) > 0 { LogActionFindings(..., toolDropFindings(drops), ...); warnUnrecordedDrops(...) }
+}
+
+// item_key `capability_gap:tool:<page>` — the SAME key builderForPageType's unavailable-builder
+// arm mints, so the two paths CO-DEDUP on the partial unique index: one page, one gap.
